#define main legacy_main
#include "qkv-cuda/main.cu"
#undef main
#include <vector>
int main(){const int BT=128,C=64,OC=192,N=BT*OC;std::vector<float>a(BT*C),w(OC*C),b(OC),out(N),want(N);for(int i=0;i<BT*C;i++)a[i]=float(i%17-8)/16;for(int i=0;i<OC*C;i++)w[i]=float(i%13-6)/16;for(int i=0;i<OC;i++)b[i]=float(i%7-3)/8;for(int t=0;t<BT;t++)for(int o=0;o<OC;o++){long z=32*(o%7-3);for(int k=0;k<C;k++)z+=((t*C+k)%17-8)*((o*C+k)%13-6);want[t*OC+o]=float(z)/256;}float*A,*W,*B,*O;cudaCheck(cudaMalloc(&A,a.size()*4));cudaCheck(cudaMalloc(&W,w.size()*4));cudaCheck(cudaMalloc(&B,b.size()*4));cudaCheck(cudaMalloc(&O,N*4));cudaCheck(cudaMemcpy(A,a.data(),a.size()*4,cudaMemcpyHostToDevice));cudaCheck(cudaMemcpy(W,w.data(),w.size()*4,cudaMemcpyHostToDevice));cudaCheck(cudaMemcpy(B,b.data(),b.size()*4,cudaMemcpyHostToDevice));matmul_forward1(O,A,W,B,1,BT,C,OC);for(int trial=1;trial<=5;trial++){cudaCheck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<100;k++)matmul_forward1(O,A,W,B,1,BT,C,OC);double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/100;cudaCheck(cudaMemcpy(out.data(),O,N*4,cudaMemcpyDeviceToHost));double err=0;bool ok=true;for(int i=0;i<N;i++){err=std::max(err,double(fabs(out[i]-want[i])));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-want[i])<=.1;}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),4,N,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.15g,\"timing_region\":\"default1_naive_matmul_bias_host_sync_mean\",\"jit_excluded\":true,\"internal_repeats\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",N,err,path,N);if(!ok)return 1;}cudaFree(A);cudaFree(W);cudaFree(B);cudaFree(O);}
